head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > escape]<br/>렌더링 과정에서 각 아이템의 라벨값을 이스케이프 처리 할지 설정합니다.",
    "validation" : [
        "true (default) 설정 시 '&', '&lt;', '&gt;', 큰따옴표, 작은따옴표 등의 특수문자를 이스케이프 처리합니다.",
        "true 설정 시 렌더링 과정에서 특수문자를 이스케이프 처리하므로 결과적으로 모든 문자가 화면에 표시됩니다.",
        "false 설정 시 아이템의 라벨값에 이스케이프 처리를 하지 않습니다.",
        "속성값 미설정 시 기본값 true 가 적용되어 특수문자를 이스케이프 처리합니다.",
        "tooltip 속성값은 escape 속성에 관계없이 이스케이프 처리되지 않습니다.",
        "accessibility=true 이면 라벨이 button 요소로 렌더링되고, accessibility=false 이면 td 요소로 렌더링되며, 두 경우 모두 escape=true 설정이 동일하게 적용됩니다.",
        "addItem() 메소드로 아이템을 추가하는 경우도 escape 속성이 적용됩니다.",
        "아이템 라벨값은 '<xf:choices> 정의 → useItemLocale 적용 → escape 적용' 순서로 렌더링됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 각 target 의 라벨 DOM (button or td) 의 innerHTML / textContent 출력
scwin.btn_getLabel_onclick = function (e) {
    for (var i = 1; i <= 5; i++) {
        var comp = eval('target' + i);
        // accessibility=true → button, accessibility=false → td 에 라벨 렌더링
        var btnElem = document.querySelector("button[id*='" + comp.getID() + "_li_item_0'], #" + comp.getID() + " button");
        var tdElem = document.querySelector("#" + comp.getID() + "_table tr td");

        var labelElem;
        if (btnElem && btnElem.closest("#" + comp.getID())) {
            labelElem = btnElem;
        } else if (tdElem) {
            labelElem = tdElem;
        }

        if (labelElem) {
            wf_body_bottom.getObj("scwin").setReturnValue("target" + i + " (" + labelElem.tagName + ") innerHTML : " + labelElem.innerHTML);
            wf_body_bottom.getObj("scwin").setReturnValue("target" + i + " (" + labelElem.tagName + ") textContent : " + labelElem.textContent);
        }
    }
};



// addItem 으로 아이템 추가 후 escape 적용 여부 확인 (target1: escape=true, target2: escape=false)
scwin.btn_addItem_onclick = function (e) {
    target1.addItem("3", "<tag>added", undefined, false);
    target2.addItem("3", "<tag>added", undefined, false);

    // 추가된 아이템(index=2) 의 라벨 DOM 확인
    var td1 = document.querySelector("#target1_table tr:nth-child(3) td");
    var td2 = document.querySelector("#target2_table tr:nth-child(3) td");

    if (td1) {
        wf_body_bottom.getObj("scwin").setReturnValue("target1(escape=true) addItem innerHTML : " + td1.innerHTML);
    }
    if (td2) {
        wf_body_bottom.getObj("scwin").setReturnValue("target2(escape=false) addItem innerHTML : " + td2.innerHTML);
    }
};



// 각 target 의 render 영역 textContent 출력
// (escape=true 면 특수문자 그대로 표시, escape=false 면 태그 처리되어 텍스트 부분만 표시)
scwin.btn_getTextContent_onclick = function (e) {
    for (var i = 1; i <= 5; i++) {
        var comp = eval('target' + i);
        wf_body_bottom.getObj("scwin").setReturnValue("target" + i + " textContent : " + comp.render.textContent);
    }
};



// target1 클릭 시 tooltip 풍선 정보 출력
// (Playwright 가 target1 hover → tooltip 풍선 표시 → 클릭 → 결과 출력)
// 기대 동작: tooltip 은 escape 속성 무관하게 이스케이프 처리되지 않음
scwin.target1_onclick = function (e) {
    $c.gcm.getTooltipInfo(wf_body_bottom);
};
